import React from 'react';
import styled from 'styled-components';
import { Slide } from 'react-slideshow-image';
import katowice from '../../images/katowice.jpg';
import work from '../../images/work.jpg';
import electrician from '../../images/electrician.jpg';
import { useSpring, animated, config } from "react-spring";

const slideImages = [
    katowice,
    work,
    electrician
];

const properties = {
    duration: 5000,
    transitionDuration: 500,
    infinite: true,
    indicators: true,
    arrows: true,
    pauseOnHover: true,
    onChange: (oldIndex, newIndex) => {
        console.log(`slide transition from ${oldIndex} to ${newIndex}`);
    }
}

const Slideshow = () => {
    const sliderAnimation = useSpring({
        from: { transform: 'translate3d(0, 30px, 0)', opacity: 0 },
        to: { transform: 'translate3d(0, 0, 0)', opacity: 1 },
        delay: 800,
        config: config.wobbly,
    });

    return (
        <SlideContainer style={sliderAnimation}>
            <Slide {...properties}>
                <div className="each-slide">
                    <div style={{
                        'backgroundImage': `url(${slideImages[0]})`,
                        'height': '450px',
                        'width': '1440px',
                        'backgroundPosition': 'center',
                        'backgroundSize': 'cover',
                    }}>
                        <span>Slide 1</span>
                    </div>
                </div>
                <div className="each-slide">
                    <div style={{ 'backgroundImage': `url(${slideImages[1]})`, 'height': '400px' }}>
                        <span>Slide 2</span>
                    </div>
                </div>
                <div className="each-slide">
                    <div style={{ 'backgroundImage': `url(${slideImages[2]})`, 'height': '400px' }}>
                        <span>Slide 3</span>
                    </div>
                </div>
            </Slide>
        </SlideContainer>
    )
}

export default Slideshow

const SlideContainer = styled(animated.nav)`
    margin: 8.5rem auto;
    height: 40%;
    width: 100%;
`;
